hero-cherry-tree.source:
const H = params.height, S = params.spread;
const sy = H / 5.5, sx = S / 7;
const bark = { preset: 'bark', color: params.barkColor, roughness: 0.95, flatShading: true };
const blossom = { preset: 'leaf', roughness: 0.85, flatShading: true };
const petalMat = { preset: 'fabric', roughness: 0.9 };
// trunk: tapered twisting segments
const th = 2.2 * sy;
const NS = 10;
const tp = [];
for (let i = 0; i <= NS; i++) {
  const t = i / NS;
  tp.push([Math.sin(t * 6) * 0.18 * sx * (0.4 + t), t * th, Math.cos(t * 5) * 0.16 * sx * (0.4 + t)]);
}
for (let i = 0; i < NS; i += 2) {
  const t = i / NS;
  const r = (0.26 - 0.12 * t) * sx;
  api.add(api.tube([tp[i], tp[i + 1], tp[i + 2]], r, 9), bark);
  api.add(api.sphere(r * 0.95, 1).translate(tp[i + 2][0], tp[i + 2][1], tp[i + 2][2]), bark);
}
api.add(api.cone(0.55 * sx, 0.6 * sy, 10).translate(tp[0][0], 0.3 * sy, tp[0][2]), bark);
const top = tp[NS];
const nb = 6;
const branches = [];
const a0 = api.rng() * 6;
for (let b = 0; b < nb; b++) {
  const a = a0 + (b / nb) * Math.PI * 2 + (api.rng() - 0.5) * 0.3;
  const len = (2.7 + api.rng() * 0.6) * sx;
  const rise = (1.5 + api.rng() * 0.7) * sy;
  const st = tp[NS - (b % 3)];
  const pts = [];
  for (let i = 0; i <= 8; i++) {
    const t = i / 8;
    const w = Math.sin(t * 5 + b * 1.7) * 0.18;
    const rr = len * Math.pow(t, 0.9);
    pts.push([st[0] + Math.cos(a + w) * rr, st[1] + rise * (1 - (1 - t) * (1 - t)) , st[2] + Math.sin(a + w) * rr]);
  }
  api.add(api.tube(pts.slice(0, 4), 0.17 * sx, 7), bark);
  api.add(api.tube(pts.slice(3, 7), 0.11 * sx, 6), bark);
  api.add(api.tube(pts.slice(6), 0.07 * sx, 5), bark);
  const e = pts[4];
  const a2 = a + (b % 2 ? 0.7 : -0.7);
  const f = [e, [e[0] + Math.cos(a2) * 0.6 * sx, e[1] + 0.4 * sy, e[2] + Math.sin(a2) * 0.6 * sx], [e[0] + Math.cos(a2) * 1.2 * sx, e[1] + 0.7 * sy, e[2] + Math.sin(a2) * 1.2 * sx]];
  api.add(api.tube(f, 0.065 * sx, 5), bark);
  branches.push({ pts, f, a });
}
const colors = [params.blossomColor, api.mix(params.blossomColor, '#ffffff', 0.4), api.mix(params.blossomColor, '#d9648f', 0.45), api.mix(params.blossomColor, '#ffe3ee', 0.6)];
const N = params.clumps;
let all = null;
const nHang = Math.max(3, Math.round(N * 0.14));
function clump(x, y, z, r, c, id) {
  const m = api.sphere(r, 2).scale(1, 0.8, 1).displace((px, py, pz) => api.noise3(px * 2 + id, py * 2, pz * 2) * 0.16 * r).translate(x, y, z);
  m.vertexColor((px, py, pz) => api.mix(c, '#ffffff', Math.max(0, Math.min(0.3, (py - y) * 0.25))));
  if (all) all.merge(m); else all = m;
}
for (let i = 0; i < N; i++) {
  const br = branches[i % nb];
  const c = colors[Math.floor(api.rng() * colors.length)];
  const r = (0.6 + api.rng() * 0.7) * Math.min(sx, 1.4);
  if (i < nHang) {
    const bb = branches[i % nb];
    const e = bb.pts[7];
    const ox = (api.rng() - 0.5) * 0.8 * sx, oz = (api.rng() - 0.5) * 0.8 * sx;
    const y = Math.max(2.6 * sy, e[1] - (1.0 + api.rng() * 0.5) * sy);
    const x = e[0] + ox + Math.cos(bb.a) * 0.3 * sx, z = e[2] + oz + Math.sin(bb.a) * 0.3 * sx;
    api.add(api.tube([e, [(e[0] + x) / 2, (e[1] + y) / 2 + 0.2, (e[2] + z) / 2], [x, y + 0.2, z]], 0.035 * sx, 4), bark);
    clump(x, y, z, r * 0.8, c, i);
    continue;
  }
  let t = 0.4 + api.rng() * 0.6;
  let p;
  if (api.rng() < 0.3) {
    p = br.f[1 + Math.floor(api.rng() * 2)];
  } else {
    const k = Math.min(7, Math.floor(t * 8));
    p = br.pts[k];
  }
  const x = p[0] + (api.rng() - 0.5) * 1.2 * sx;
  const z = p[2] + (api.rng() - 0.5) * 1.2 * sx;
  let y = p[1] + (0.3 + api.rng() * 0.8) * sy;
  y = Math.max(3.2 * sy, Math.min(5.0 * sy, y));
  clump(x, y, z, r, c, i);
}
// a couple at the crown, fewer in centre
clump(top[0], 4.5 * sy, top[2], 0.8 * Math.min(sx, 1.3), colors[1], 999);
clump(top[0] + 0.9 * sx, 4.2 * sy, top[2] - 0.5 * sx, 0.7 * Math.min(sx, 1.3), colors[0], 998);
api.add(all, blossom);
// petals
let pm = null;
const pc = ['#f8b9cf', '#ffd6e4', '#f29ab8', '#fde4ee'];
for (let i = 0; i < params.petals; i++) {
  const a = api.rng() * Math.PI * 2;
  const d = 0.3 + Math.sqrt(api.rng()) * 3.2 * sx;
  const col = pc[Math.floor(api.rng() * pc.length)];
  const p = api.cylinder(0.03, 0.03, 0.006, 6).scale(1 + api.rng() * 0.5, 1, 0.8).rotate(0, api.rng() * 360, 0).translate(Math.cos(a) * d, 0.01 + api.rng() * 0.01, Math.sin(a) * d);
  p.vertexColor(() => col);
  if (pm) pm.merge(p); else pm = p;
}
if (pm) api.add(pm, petalMat);
api.collider({ kind: 'cylinder', radius: 0.35 * sx, halfHeight: th / 2, offset: [0, th / 2, 0] });
return api.build();

hero-gazebo.source:
const sx = params.width / 4, sy = params.height / 4.6;
const R = 2.0;
const white = { preset: 'wood', color: params.color, roughness: 0.55 };
const deck = { preset: 'wood', color: params.deckColor, roughness: 0.8 };
const slate = { preset: 'stone', roughness: 0.85, flatShading: true, vertexColors: true };
const iron = { preset: 'metal', color: '#2a2c30', metalness: 0.7, roughness: 0.4 };
function A(m, mat) { m.scale(sx, sy, sx); api.add(m, mat); }
const D = Math.PI / 180;
const ap = R * Math.cos(22.5 * D);
const side = 2 * R * Math.sin(22.5 * D);
// base
A(api.cylinder(R * 1.02, R * 1.02, 0.42, 8).rotate(0, 22.5, 0).translate(0, 0.21, 0), white);
A(api.cylinder(R * 1.08, R * 1.08, 0.08, 8).rotate(0, 22.5, 0).translate(0, 0.46, 0), deck);
// steps
A(api.box(1.4, 0.17, 0.4).translate(0, 0.085, ap * 1.08 + 0.55), deck);
A(api.box(1.2, 0.33, 0.4).translate(0, 0.165, ap * 1.08 + 0.2), deck);
const top = 0.5, Hc = 2.6, beamY = top + Hc;
const profile = [[0, 0], [0.09, 0], [0.09, 0.1], [0.05, 0.16], [0.045, 0.4], [0.065, 0.9], [0.045, 1.5], [0.04, 2.1], [0.055, 2.4], [0.085, 2.47], [0.085, 2.6], [0, 2.6]];
for (let i = 0; i < 8; i++) {
  const a = (i * 45 + 22.5) * D;
  const x = Math.cos(a) * R, z = Math.sin(a) * R;
  A(api.lathe(profile, 12).translate(x, top, z), white);
  api.collider({ kind: 'cylinder', radius: 0.09 * sx, halfHeight: Hc / 2 * sy, offset: [x * sx, (top + Hc / 2) * sy, z * sx] });
}
for (let i = 0; i < 8; i++) {
  const th = i * 45 + 45;
  const t = th * D;
  const cx = Math.cos(t) * ap, cz = Math.sin(t) * ap;
  const phi = -(th + 90);
  // beam
  A(api.box(side + 0.2, 0.2, 0.14).rotate(0, phi, 0).translate(cx, beamY - 0.05, cz), white);
  // brackets
  const L = side / 2 - 0.08;
  const tx = -Math.sin(t), tz = Math.cos(t);
  const b1 = api.extrude([[0, 0], [0.5, 0], [0.08, -0.08], [0, -0.5]], 0.05).rotate(0, phi, 0).translate(cx - tx * L, beamY - 0.15, cz - tz * L);
  const b2 = api.extrude([[0, 0], [0, -0.5], [-0.08, -0.08], [-0.5, 0]], 0.05).rotate(0, phi, 0).translate(cx + tx * L, beamY - 0.15, cz + tz * L);
  A(b1, white); A(b2, white);
  A(api.sphere(0.04, 1).rotate(0, 0, 0).translate(cx - tx * (L - 0.22) , beamY - 0.3, cz - tz * (L - 0.22)), white);
  A(api.sphere(0.04, 1).translate(cx + tx * (L - 0.22), beamY - 0.3, cz + tz * (L - 0.22)), white);
  if (i === 1) continue;
  // railing
  const rl = side - 0.15;
  const rb = top + 0.08;
  A(api.box(rl, 0.07, 0.07).rotate(0, phi, 0).translate(cx, rb + 0.12, cz), white);
  A(api.box(rl, 0.09, 0.1).rotate(0, phi, 0).translate(cx, rb + 0.9, cz), white);
  const n = params.balusters;
  for (let k = 0; k < n; k++) {
    const u = ((k + 0.5) / n - 0.5) * (rl - 0.1);
    A(api.cylinder(0.022, 0.022, 0.8, 6).translate(cx + tx * u, rb + 0.5, cz + tz * u), white);
  }
}
// roof
const rr = R * 1.25, y0 = beamY + 0.05, rise = 1.1;
const prof = [[0, y0], [rr, y0], [rr, y0 + 0.06]];
for (let k = 1; k <= 14; k++) {
  const t = k / 14;
  prof.push([rr * Math.pow(1 - t, 1.15) + 0.0001, y0 + 0.06 + rise * t - 0.18 * Math.sin(t * Math.PI)]);
}
const roof = api.lathe(prof, 8).rotate(0, 22.5, 0);
const c1 = params.roofColor, c2 = api.mix(params.roofColor, '#15181c', 0.35);
roof.vertexColor((x, y, z) => (Math.floor((y - y0) / 0.13) % 2 === 0 ? c1 : c2));
A(roof, slate);
A(api.cylinder(0.3, 0.3, 0.1, 8).translate(0, y0 + rise + 0.05, 0), white);
// finial
const yt = y0 + 0.06 + rise;
A(api.sphere(0.1, 2).translate(0, yt + 0.1, 0), white);
A(api.cylinder(0.015, 0.015, 0.4, 6).translate(0, yt + 0.3, 0), iron);
A(api.box(0.4, 0.03, 0.03).translate(0, yt + 0.35, 0), iron);
A(api.cone(0.05, 0.12, 6).rotate(0, 0, -90).translate(0.26, yt + 0.35, 0), iron);
A(api.box(0.1, 0.1, 0.01).translate(-0.2, yt + 0.37, 0), iron);
// colliders
api.collider({ kind: 'cylinder', radius: R * 1.05 * sx, halfHeight: 0.25 * sy, offset: [0, 0.25 * sy, 0] });
api.collider({ kind: 'box', halfExtents: [0.7 * sx, 0.165 * sy, 0.2 * sx], offset: [0, 0.165 * sy, (ap * 1.08 + 0.2) * sx] });
return api.build();
